import * as React from 'react'

import './stepper.css'

export type StepperProps = {
    steps: string[]
    /** Index of the current step. Earlier steps show as done. */
    current: number
    /** Accessible name for the list, e.g. "Checkout progress". */
    label?: string
    className?: string
}

// An ordered list: the current step has aria-current="step", and done steps say so
// in text, not just with a tick. The connecting line fills as you advance.
const Stepper = ({ steps, current, label = 'Progress', className }: StepperProps) => (
    <ol className={['rad-fx-stepper', className].filter(Boolean).join(' ')} aria-label={label}>
        {steps.map((step, i) => {
            const state = i < current ? 'done' : i === current ? 'current' : 'upcoming'
            return <li key={step} className="rad-fx-step" data-state={state} aria-current={state === 'current' ? 'step' : undefined}>
                <span className="rad-fx-step-marker" aria-hidden="true">
                    <span className="rad-fx-step-number">{i + 1}</span>
                    <svg viewBox="0 0 24 24" focusable="false"><path d="M6 12.5 L10 16.5 L18 8" pathLength={1} /></svg>
                </span>
                <span className="rad-fx-step-label">
                    {step}
                    {state === 'done' ? <span className="rad-fx-step-sr"> (completed)</span> : null}
                </span>
                {i < steps.length - 1 ? <span className="rad-fx-step-line" aria-hidden="true" /> : null}
            </li>
        })}
    </ol>
)

export default Stepper

.rad-fx-stepper {
    display: flex;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
}

.rad-fx-step {
    position: relative;
    display: flex;
    flex: 1;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    min-width: 90px;
    text-align: center;
    font-size: 0.875rem;
}

.rad-fx-step-marker {
    position: relative;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border: 2px solid rgba(127, 127, 127, 0.5);
    border-radius: 50%;
    background: var(--rad-fx-stepper-surface, transparent);
    font-weight: 600;
    transition: border-color 300ms ease, background 300ms ease, transform 300ms cubic-bezier(0.3, 1.5, 0.5, 1);
}

.rad-fx-step-marker svg {
    position: absolute;
    width: 18px;
    height: 18px;
    fill: none;
    stroke: #0b0b0f;
    stroke-width: 2.6;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 350ms ease 150ms;
}

.rad-fx-step[data-state='current'] .rad-fx-step-marker {
    border-color: var(--rad-fx-stepper-color, #a78bfa);
    transform: scale(1.1);
}

.rad-fx-step[data-state='done'] .rad-fx-step-marker {
    border-color: var(--rad-fx-stepper-color, #a78bfa);
    background: var(--rad-fx-stepper-color, #a78bfa);
}

.rad-fx-step[data-state='done'] .rad-fx-step-number { opacity: 0; }
.rad-fx-step[data-state='done'] .rad-fx-step-marker svg { stroke-dashoffset: 0; }

.rad-fx-step[data-state='current'] .rad-fx-step-label { font-weight: 600; }

/* Visually hidden "(completed)" so state isn't conveyed by the tick alone. */
.rad-fx-step-sr {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
}

.rad-fx-step-line {
    position: absolute;
    top: 17px;
    left: calc(50% + 22px);
    right: calc(-50% + 22px);
    height: 2px;
    background: rgba(127, 127, 127, 0.35);
    overflow: hidden;
}

.rad-fx-step-line::after {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--rad-fx-stepper-color, #a78bfa);
    transform: scaleX(0);
    transform-origin: 0 50%;
    transition: transform 450ms cubic-bezier(0.6, 0.1, 0.3, 1);
}

.rad-fx-step[data-state='done'] .rad-fx-step-line::after { transform: scaleX(1); }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-step-marker, .rad-fx-step-marker svg, .rad-fx-step-line::after { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-step-marker,
[data-rad-fx-motion='reduce'] .rad-fx-step-marker svg,
[data-rad-fx-motion='reduce'] .rad-fx-step-line::after { transition: none; }
